use tower_http::services::ServeDir;
use tower_http::trace::TraceLayer;

pub async fn initialize(app_state: &AppState) -> anyhow::Result<()> {
    db::run_migrations(&app_state.database_connection).await?;
    app_state.load_ai_configuration().await;
    authentication::service::seed_admin_user(app_state).await;
    demo::service::seed_demo_data(app_state).await;
    Ok(())
}

pub async fn refresh_stale_suggested_questions(app_state: &AppState) {
    suggested_question::service::refresh_all_stale(app_state).await;
}

pub fn build_app(app_state: AppState) -> Router {
    let frontend_dir = PathBuf::from(app_state.config.frontend_dir.as_ref());
    let index_path = frontend_dir.join("index.html");
    let static_files_service = ServeDir::new(&frontend_dir);

    let app = Router::new()
        .nest("/api/v1/monitor", monitor::routes())
        .nest("/api/v1/auth", authentication::routes(app_state.clone()))
        .nest(
            "/api/v1/dashboard",
            dashboard::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/connection",
            connection::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/notebook",
            notebook::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/cell",
            cell::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/canvas",
            canvas::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/search",
            search::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .nest(
            "/api/v1/conversational_analytics",
            conversational_analytics::routes(app_state.clone()).layer(
                axum::middleware::from_fn_with_state(
                    app_state.clone(),
                    middlewares::auth_middleware_fn,
                ),
            ),
        )
        .nest(
            "/api/v1/ai_configuration",
            ai_configuration::routes(app_state.clone()).layer(
                axum::middleware::from_fn_with_state(
                    app_state.clone(),
                    middlewares::auth_middleware_fn,
                ),
            ),
        )
        .nest(
            "/api/v1/suggested_question",
            suggested_question::routes(app_state.clone()).layer(
                axum::middleware::from_fn_with_state(
                    app_state.clone(),
                    middlewares::auth_middleware_fn,
                ),
            ),
        )
        .nest(
            "/api/v1/ai_summary",
            ai_summary::routes(app_state.clone()).layer(axum::middleware::from_fn_with_state(
                app_state.clone(),
                middlewares::auth_middleware_fn,
            )),
        )
        .fallback_service(static_files_service)
        .layer(middleware::from_fn(move |req: Request, next: Next| {
            let index_path = index_path.clone();
            async move {
                let res = next.run(req).await;
                let (parts, body) = res.into_parts();
                let status = parts.status;

                // If the response is 404, serve index.html instead
                if status == StatusCode::NOT_FOUND {
                    match tokio::fs::read_to_string(&index_path).await {
                        Ok(html) => Html(html).into_response(),
                        Err(_) => Response::from_parts(parts, body),
                    }
                } else {
                    Response::from_parts(parts, body)
                }
            }
        }))
        .layer(TraceLayer::new_for_http())
        .layer(CookieManagerLayer::new());

    let cors = if app_state.config.environment == "development" {
        CorsLayer::new()
            .allow_methods([
                Method::GET,
                Method::POST,
                Method::PUT,
                Method::PATCH,
                Method::DELETE,
            ])
            .allow_origin(HeaderValue::from_str("http://localhost").unwrap())
            .allow_credentials(true)
            .allow_headers([header::CONTENT_TYPE])
    } else {
        CorsLayer::new()
            .allow_methods([
                Method::GET,
                Method::POST,
                Method::PUT,
                Method::PATCH,
                Method::DELETE,
            ])
            .allow_credentials(true)
            .allow_headers([header::CONTENT_TYPE])
    };
    app.layer(cors)
}

pub async fn run() -> anyhow::Result<()> {
    dotenv().ok();
    let app_state = AppState::from_env().await?;
    initialize(&app_state).await?;
    scheduler::start(app_state.clone()).await;
    let listener =
        tokio::net::TcpListener::bind(format!("0.0.0.0:{}", app_state.config.port)).await?;
    tracing::debug!("listening on {}", listener.local_addr()?);
    axum::serve(listener, build_app(app_state)).await?;
    Ok(())
}
